type CartLine = { sku: string; quantity: number };
type CartResult =
  | { ok: true; lines: CartLine[] }
  | { ok: false; message: string };

function readCartResponse(status: number, body: unknown): CartResult {
  // TODO: map 401, other failures, and malformed bodies before returning success
  return { ok: true, lines: body as CartLine[] };
}
